"""Greedy paragraph-preserving text wrapping."""
import re


def wrap(text, width):
    if isinstance(width, bool) or not isinstance(width, int):
        raise ValueError("width must be an integer")
    if width < 1:
        raise ValueError("width must be at least 1")
    paragraphs = []
    for block in re.split(r"\n[^\S\n]*(?:\n[^\S\n]*)*", "\n" + text):
        words = block.split()
        if not words:
            continue
        lines = []
        line = words[0]
        for word in words[1:]:
            if len(line) + 1 + len(word) <= width:
                line += " " + word
            else:
                lines.append(line)
                line = word
        lines.append(line)
        paragraphs.append("\n".join(lines))
    return "\n\n".join(paragraphs)
